set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';import {discoverNewsLinks} from './src/web/configurableNewsParser.mjs';import {parsePublicPublicationFeed} from './src/web/newsDateContext.mjs';const root='/var/lib/news-flow/qc-public24-20261123',require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:[...registry.allowedDomains,'thoibaobatdongsan.n.nu'],siteCooldown:false,maxWireRequests:18}),r={at:new Date().toISOString(),checks:[]},UA='Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36',jobs=[{site:'tieudungso.vn',url:'https://tieudungso.vn/',standard:true},{site:'tieudungso.vn',url:'https://tieudungso.vn/',standard:false},{site:'tieudungso.vn',url:'https://tieudungso.vn/feed/',standard:true},{site:'tieudungso.vn',url:'https://tieudungso.vn/wp-json/wp/v2/posts?per_page=5&_embed=author,wp:featuredmedia',standard:true},{site:'thoibaobatdongsan.net',url:'https://thoibaobatdongsan.n.nu/rss.xml',standard:true},{site:'thoibaobatdongsan.net',url:'https://thoibaobatdongsan.n.nu/blogg',standard:true}];try{for(const j of jobs){const p=await driver.get('qc-public24-controls-'+r.checks.length,j.url,registry.sources.get(j.site).config,[],{reviewFailed:true,taskRole:'publisher_dependency',headers:j.standard?{'User-Agent':UA}:{}}),o={...j,error:p.error,statusCode:p.statusCode,finalUrl:p.finalUrl};if(p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));const $=ch.load(p.html);o.title=$('title').text().trim();o.notice=$('body').clone().find('script,style').remove().end().text().replace(/\s+/g,' ').trim().slice(0,250);o.canonical=$('link[rel="canonical"]').attr('href');if(!p.error){const f=parsePublicPublicationFeed(p.html,p.finalUrl||j.url);o.feedItems=f.items.length;o.feedSample=f.items.slice(0,2);o.links=discoverNewsLinks(p.html,p.finalUrl||j.url,{domain:j.site,allowedHosts:registry.sources.get(j.site).config.allowedHosts,legacy:{}}).articles.slice(0,8);try{const d=JSON.parse(p.html);o.jsonType=Array.isArray(d)?'array':typeof d;if(Array.isArray(d))o.posts=d.map(p=>({id:p.id,url:p.link,dateGmt:p.date_gmt,title:p.title?.rendered,chars:p.content?.rendered?.length}));}catch{}}}r.checks.push(o);console.log(JSON.stringify({...o,feedSample:undefined,notice:o.notice}));}fs.writeFileSync(root+'/candidate-controls.json',JSON.stringify(r,null,2));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-public24-20261123/candidate-controls.json "$upload_dir/.qc-public24-candidate-controls.json"
